#!/usr/bin/env python3
"""Audit endpoint/Q defect restriction on the marked D03 exit interval."""
import json,subprocess,tempfile
from pathlib import Path
R=Path(__file__).resolve().parents[2];s=R/'research/voevodsky/check_d03_q0_endpoint_exit_flags.rs';e=Path(tempfile.gettempdir())/(s.stem+'.exe');subprocess.run(['rustc','--edition=2021','-D','warnings','-O',str(s),'-o',str(e)],check=True);x=json.loads(subprocess.check_output([str(e)],text=True));f=x['factorization_test']
checks={'unique_flip':f['q0_compatible_central_flip'].startswith('UNIQUE'),'marked_road':f['marked_F03_flag'].startswith('UNIQUE'),'marked_endpoint':f['marked_q0_flag'].startswith('UNIQUE'),'BM_span':f['endpoint_relative_BM_span'].startswith('PASS'),'Q_leg':f['generic_Q_leg'].startswith('PASS'),'generization':f['road_generization_before_base_change'].startswith('DERIVED'),'BC':f['normalized_BC'].startswith('PASS'),'Tor_missing':f['full_extraordinary_Tor_map']=='NOT CONSTRUCTED'}
assert all(checks.values()),checks
out={'schema':'marici.voevodsky.CR1-alpha-endpoint-Q-defect-restriction.v1','action':'CR1ALPHA2a_construct_endpoint_Q_defect_restriction','outcome':'+-','proved':['unique x3-marked endpoint-relative interval F03-Z3-v10-...-q0','primitive relative-BM class','nonzero carrier Q leg at F03','unfitted road generization b0=+x1','endpoint coefficient a0=-1','normalized BC equation b0=-x1*a0'],'unresolved':['opposite q2/sheet endpoint restriction','reciprocal-standard to original-BM Tor1 extraordinary map'],'produces':['positive_sheet_q0_endpoint_Q_defect_restriction'],'refinement':['CR1ALPHA2a1_construct_opposite_q2_endpoint_Q_restriction','CR1ALPHA2a2_pair_q0_q2_restrictions_under_reflection','CR1ALPHA2a3_compute_defect_parity'],'next':'CR1ALPHA2a1_construct_opposite_q2_endpoint_Q_restriction','metric_delta':{'resolved_alpha_subgates':1,'remaining_endpoint_restrictions':-1,'new_typed_interfaces':1,'gate_entropy_bits':-2.0},'checks':checks,'passed':True};p=R/'research/voevodsky/results/CR1_alpha_endpoint_Q_defect_restriction.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'passed':True,'outcome':'+-','endpoint':'q0','Q_leg':True,'new_interfaces':1,'next':out['next']}))
